// Build-time only: reproduce Ebiten's imageToBytes(image, true) conversion with
// Go's standard image.RGBA + draw.Src path. No rendering/GLFW/engine changes.
package main
import("encoding/json";"image";"image/draw";_ "image/png";"os";"path/filepath")
func main(){root:=os.Args[1];var atlas struct{Rects map[string][]int `json:"rects"`};data,e:=os.ReadFile(filepath.Join(root,"assets/pixel-renderer/atlas-layout.json"));if e!=nil{panic(e)};if e=json.Unmarshal(data,&atlas);e!=nil{panic(e)};result:=map[string]any{};for key:=range atlas.Rects{path:=filepath.Join(root,"assets",key+".png");if len(key)>=15&&key[:15]=="derived/circle/"{path=filepath.Join(root,"assets/pixel-renderer/circle-"+key[15:]+".png")}else if len(key)>=13&&key[:13]=="derived/boss/"{path=filepath.Join(root,"assets/pixel-renderer/atlas.png")}else if len(key)<10||key[:10]!="reference/"{continue};f,e:=os.Open(path);if e!=nil{panic(e)};src,_,e:=image.Decode(f);f.Close();if e!=nil{panic(e)};if len(key)>=13&&key[:13]=="derived/boss/"{r:=atlas.Rects[key];src=src.(interface{SubImage(image.Rectangle) image.Image}).SubImage(image.Rect(r[0],r[1],r[0]+r[2],r[1]+r[3]))};b:=src.Bounds();dst:=image.NewRGBA(image.Rect(0,0,b.Dx(),b.Dy()));draw.Draw(dst,dst.Bounds(),src,b.Min,draw.Src);pixels:=make([]int,len(dst.Pix));partial:=false;for i,v:=range dst.Pix{pixels[i]=int(v);if i%4==3&&v>0&&v<255{partial=true}};result[key]=map[string]any{"width":b.Dx(),"height":b.Dy(),"pixels":pixels,"partial":partial}};out,e:=os.Create(filepath.Join(root,"assets/pixel-renderer/pixels.json"));if e!=nil{panic(e)};defer out.Close();enc:=json.NewEncoder(out);if e=enc.Encode(result);e!=nil{panic(e)}}
